<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { parkingResidentApi } from '../../api/stageH.js'
import { apiMessage } from '../../api/http.js'
import StatusTag from '../../components/common/StatusTag.vue'
import { displayEnum, formatMoney } from '../../constants/presentation.js'

const loading = ref(false), eligibility = ref([]), vehicles = ref([]), applications = ref([]), permits = ref([])
const vehicle = reactive({ plateNumber: '', vehicleType: 'CAR', brand: '', color: '' })
const application = reactive({ vehicleId: null, propertyUnitId: null, requestedMonths: 1 })
const eligibleOptions = computed(() => eligibility.value.filter(item => item.eligible === 'YES'))
const selectedEligibility = computed(() => eligibility.value.find(item => item.propertyUnitId === application.propertyUnitId))
const expectedRate = computed(() => selectedEligibility.value ? (selectedEligibility.value.activePermitCount || 0) === 0 ? 200 : 1200 : null)
async function load () { loading.value = true; try { const [a, b, c, d] = await Promise.all([parkingResidentApi.eligibility(), parkingResidentApi.vehicles(), parkingResidentApi.applications(), parkingResidentApi.permits()]); eligibility.value = a.data; vehicles.value = b.data; applications.value = c.data; permits.value = d.data } catch (e) { ElMessage.error(apiMessage(e, '车证信息加载失败')) } finally { loading.value = false } }
async function addVehicle () { try { await parkingResidentApi.createVehicle(vehicle); Object.assign(vehicle, { plateNumber: '', vehicleType: 'CAR', brand: '', color: '' }); ElMessage.success('车辆已添加'); load() } catch (e) { ElMessage.error(apiMessage(e, '车辆添加失败')) } }
async function submit () { try { await parkingResidentApi.submit(application); ElMessage.success('车证申请已提交，等待物业审核'); application.vehicleId = null; application.propertyUnitId = null; application.requestedMonths = 1; load() } catch (e) { ElMessage.error(apiMessage(e, '车证申请提交失败')) } }
onMounted(load)
</script>

<template>
  <section v-loading="loading" class="resident-parking-page">
    <header><p>RESIDENT PARKING</p><h1>我的车证</h1><span>登记本人车辆、查看关联房产资格并提交车证申请。</span></header>
    <section class="panel"><h2>我的申请资格</h2><el-table :data="eligibility"><el-table-column prop="communityName" label="小区" /><el-table-column label="房产"><template #default="{ row }">{{ row.buildingName }} · {{ row.unitName }} · {{ row.propertyNo }}</template></el-table-column><el-table-column label="资格来源"><template #default="{ row }">{{ displayEnum(row.source) }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }"><StatusTag :value="row.eligible" /></template></el-table-column><el-table-column label="说明"><template #default="{ row }">{{ row.reasonCode || row.remark || '—' }}</template></el-table-column></el-table></section>
    <div class="two-column"><section class="panel"><h2>登记本人车辆</h2><el-form label-position="top"><el-form-item label="车牌号" required><el-input v-model="vehicle.plateNumber" placeholder="例如：京A12345" /></el-form-item><el-form-item label="车辆类型"><el-select v-model="vehicle.vehicleType"><el-option label="小汽车" value="CAR" /><el-option label="摩托车" value="MOTORCYCLE" /><el-option label="新能源车" value="NEW_ENERGY" /></el-select></el-form-item><el-form-item label="品牌（可选）"><el-input v-model="vehicle.brand" /></el-form-item><el-form-item label="颜色（可选）"><el-input v-model="vehicle.color" /></el-form-item><el-button type="primary" @click="addVehicle">登记车辆</el-button></el-form><el-table :data="vehicles" class="compact"><el-table-column prop="plateNumber" label="车牌" /><el-table-column prop="vehicleType" label="类型" /><el-table-column prop="brand" label="品牌" /></el-table></section><section class="panel"><h2>提交车证申请</h2><el-form label-position="top"><el-form-item label="选择车辆" required><el-select v-model="application.vehicleId" placeholder="请选择本人车辆"><el-option v-for="item in vehicles" :key="item.vehicleId" :label="item.plateNumber" :value="item.vehicleId" /></el-select></el-form-item><el-form-item label="关联房产" required><el-select v-model="application.propertyUnitId" placeholder="仅显示可申请的房产"><el-option v-for="item in eligibleOptions" :key="item.propertyUnitId" :label="`${item.communityName} · ${item.buildingName} · ${item.propertyNo}`" :value="item.propertyUnitId" /></el-select></el-form-item><el-form-item label="申请月数" required><el-input-number v-model="application.requestedMonths" :min="1" :max="12" /></el-form-item><p class="quote" v-if="expectedRate">当前预计月费 ¥{{ formatMoney(expectedRate) }}；最终金额会由后端按实际有效车证数量、租期和资格复核。</p><el-button type="primary" :disabled="!application.vehicleId || !application.propertyUnitId" @click="submit">提交申请</el-button></el-form></section></div>
    <section class="panel"><h2>申请与车证记录</h2><el-table :data="applications"><el-table-column prop="applicationNo" label="申请单号" min-width="145" /><el-table-column prop="plateNumber" label="车牌" /><el-table-column label="期限"><template #default="{ row }">{{ row.requestedMonths }} 个月</template></el-table-column><el-table-column label="报价"><template #default="{ row }">¥{{ formatMoney(row.quotedTotalAmount) }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }"><StatusTag :value="row.status" /></template></el-table-column><el-table-column prop="rejectionReason" label="审核说明" /></el-table><el-table :data="permits" class="permit-table"><el-table-column prop="permitNo" label="车证编号" min-width="145" /><el-table-column prop="plateNumber" label="车牌" /><el-table-column label="有效期"><template #default="{ row }">{{ row.validFrom }} 至 {{ row.validTo }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }"><StatusTag :value="row.status" /></template></el-table-column></el-table></section>
  </section>
</template>

<style scoped>
.resident-parking-page{display:grid;gap:18px}.resident-parking-page header p{margin:0;color:var(--teal);font:700 11px Consolas,monospace;letter-spacing:.12em}.resident-parking-page header h1{margin:5px 0;color:#173b48;font-size:27px}.resident-parking-page header span{color:var(--ink-500);font-size:14px}.panel{padding:20px;border:1px solid var(--line);border-radius:14px;background:#fff}.panel h2{margin:0 0 16px;color:#173b48;font-size:17px}.two-column{display:grid;grid-template-columns:1fr 1fr;gap:18px}.el-select{width:100%}.compact{margin-top:20px}.permit-table{margin-top:18px}.quote{padding:10px;border-radius:8px;color:#846114;background:#fff8e7;font-size:12px;line-height:1.6}@media(max-width:800px){.two-column{grid-template-columns:1fr}}
</style>
